        t0 = t1;
        break
    end
    t0 = t1;
end
root2 = t0; iters2 = i;
fprintf('Root from t0=0.3: t = %.4f (in %d iterations)\n', root2, iters2);

% d) Confirm both with fzero
fzeroRoot1 = fzero(f, 0.05);
fzeroRoot2 = fzero(f, 0.3);
