% Problem: Fitting and Critiquing a One-Compartment Oral Absorption Model
% Name:
% Date:

clear; clc; close all;

Dose = 500; V = 30;
t = [0.25 0.5 1 2 4 6 8 12 24];
Cd = [5.28 8.02 11.60 11.68 8.70 5.65 4.05 1.65 0.21];

% a) Define Cmodel(t,c) and SSE(c)


% b) fminsearch from c0 = [1, 0.1]


% c) Plot data + fitted curve, and residuals vs. time


% d) Written explanation (comment or string)


% e) Re-fit from a poor initial guess and compare

solutionCode:
% a) Symbolic function and derivatives
syms xs
fSym = xs^4 - 4*xs^3 + 2;
dfSym = diff(fSym, xs);
d2fSym = diff(fSym, xs, 2);
fFun = matlabFunction(fSym);
dfFun = matlabFunction(dfSym);
d2fFun = matlabFunction(d2fSym);

x = -1:0.01:4;
figure
plot(x, fFun(x), 'LineWidth', 2)
xlabel('x')
ylabel('f(x)')
title('Cumulative Tissue Strain Model')
grid on

% b) f'(x) = 4x^3 - 12x^2 = 4x^2*(x - 3) -> roots at x = 0 (double) and x = 3 (simple)

% c) Classify x = 0
fprintf('f-prime(0) = %.4f, f-double-prime(0) = %.4f\n', dfFun(0), d2fFun(0));
% f''(0) = 0, so the second-derivative test is inconclusive at x = 0.
d3fSym = diff(fSym, xs, 3);
d3fFun = matlabFunction(d3fSym);
fprintf('f-triple-prime(0) = %.4f\n', d3fFun(0));
% The first nonzero derivative at x = 0 is the third derivative (odd order),
% so by Lecture 18's rule, x = 0 is an inflection point, not an extremum.

% d) fzero on f'(x) from two nonzero initial guesses
r1 = fzero(dfFun, 0.5);
r2 = fzero(dfFun, -0.5);
fprintf('fzero(df, 0.5) = %.4f, f-double-prime(there) = %.4f\n', r1, d2fFun(r1));
fprintf('fzero(df, -0.5) = %.4f, f-double-prime(there) = %.4f\n', r2, d2fFun(r2));
% Both converge to x = 3, not x = 0, and f''(3) = 36 > 0, confirming a true local minimum there.

% e) fminbnd directly on f(x)
[xm, fm] = fminbnd(fFun, -1, 4);
fprintf('fminbnd: x = %.4f, f(x) = %.4f\n', xm, fm);
explanation = ['fzero applied to f-prime cannot converge to x = 0 because f-prime never ' ...
    'actually changes sign there (x = 0 is a double root of the factor 4x^2), and ' ...
    'fzero fundamentally relies on detecting a sign change to bracket a root -- so ' ...
    'even initial guesses placed close to 0 on either side get pulled instead to the ' ...
    'simple root at x = 3. The ordinary second-derivative test could not classify ' ...
    'x = 0 because f-double-prime(0) = 0 as well, requiring a third derivative to reveal that ' ...
    'x = 0 is actually an inflection point, not an extremum at all. fminbnd, which ' ...
    'never relies on sign changes or derivatives in the first place, independently ' ...
    'confirms that the true minimum of f(x) over [-1,4] sits at x = 3 -- exactly ' ...
    'the same point fzero found by root-finding on the derivative.'];
disp(explanation)
